/**
 * PhysicsPathfinding - Main pathfinding component for physics worker
 *
 * Main pathfinding component for the physics worker.
 * Manages navigation grid, pathfinder, and agent controllers.
 * Supports both dynamic (player) and kinematic agents with separate tracking.
 *
 * Provides:
 * - Navigation grid with lazy generation
 * - A* pathfinding with path caching
 * - Per-agent steering and state management
 * - Integration with physics body system
 *
 * **Usage**
 *
 * ```js
 * import { physicsPathfinding } from './pathfinding';
 *
 * // Create agent for a kinematic body
 * physicsPathfinding.createAgent(bodyIndex, 'kinematic', { maxSpeed: 5 });
 *
 * // Set destination (note: bodyType is required)
 * physicsPathfinding.setDestination(bodyIndex, 'kinematic', targetPos, onArrived);
 *
 * // For player (dynamic), use convenience methods:
 * physicsPathfinding.setPlayerDestination(bodyIndex, targetPos);
 * if (physicsPathfinding.hasPlayerArrived(bodyIndex)) { ... }
 *
 * // Update in physics loop
 * physicsPathfinding.update(delta);
 * ```
 *
 * @class PhysicsPathfinding
 * @short Main pathfinding component for physics worker
 * @category Core
 * @private
 * @tags Pathfinding, Navigation, A*, Singleton
 */
export class PhysicsPathfinding {
    navGrid: PhysicsPathfindingGrid;
    pathFinder: PathFinder;
    navMesh: NavMesh;
    navMeshFinder: NavMeshFinder;
    _agents: Map<any, any>;
    _maxAgents: number;
    _gridBudget: number;
    _gridQueue: any[];
    enabled: boolean;
    _tempBounds: any;
    /**
     * Configure pathfinding system.
     *
     * @param {Object} config - Configuration options.
     * @param {number} [config.cellSize] - Navigation grid cell size.
     * @param {number} [config.agentRadius] - Agent collision radius.
     * @param {number} [config.agentHeight] - Agent standing height.
     * @param {number} [config.maxSlope] - Maximum walkable slope in radians.
     * @param {number} [config.maxStepHeight] - Maximum step height between cells.
     * @param {number} [config.referenceGroundY] - Expected ground level Y.
     * @param {number} [config.maxWalkableHeight] - Maximum height above referenceGroundY for walkable cells.
     * @param {number} [config.gridBudget] - Max cells to generate per frame.
     * @param {number} [config.maxAgents] - Maximum concurrent pathfinding agents.
     * @returns {PhysicsPathfinding} This instance for chaining.
     */
    set(config: {
        cellSize?: number;
        agentRadius?: number;
        agentHeight?: number;
        maxSlope?: number;
        maxStepHeight?: number;
        referenceGroundY?: number;
        maxWalkableHeight?: number;
        gridBudget?: number;
        maxAgents?: number;
    }): PhysicsPathfinding;
    /**
     * Initialize NavMesh from main thread compiled data.
     *
     * @param {Object} data - Serialized navmesh data from NavMeshGrid.
     * @param {Array} data.polygons - Polygon vertices and normals.
     * @param {Array} [data.edges] - Edge adjacency data.
     */
    initNavMesh(data: {
        polygons: any[];
        edges?: any[];
    }): void;
    /**
     * Get NavMesh debug data.
     *
     * @returns {Object} NavMesh debug information.
     */
    getNavMeshDebugData(): any;
    /**
     * Create a composite key for agent lookup.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type ('dynamic' or 'kinematic').
     * @returns {string} Composite key.
     * @private
     */
    private _getAgentKey;
    /**
     * Create a pathfinding agent for a body.
     *
     * @param {number} bodyIndex - Body index in physicsState.
     * @param {string} bodyType - Body type ('dynamic' or 'kinematic').
     * @param {Object} [config] - Agent configuration.
     * @param {number} [config.maxSpeed=5.0] - Maximum movement speed.
     * @param {number} [config.arrivalRadius=1.5] - Arrival detection radius.
     * @param {number} [config.avoidanceRadius=1.5] - Obstacle avoidance radius.
     * @returns {AgentController|null} Created agent or null if limit reached.
     */
    createAgent(bodyIndex: number, bodyType: string, config?: {
        maxSpeed?: number;
        arrivalRadius?: number;
        avoidanceRadius?: number;
    }): AgentController | null;
    /**
     * Create a pathfinding agent for the player with RTS-style direct position movement.
     * This is a convenience method that creates an agent with useDirectPosition: true.
     *
     * @param {number} bodyIndex - Body index (usually 0 for the player).
     * @param {Object} [config] - Agent configuration.
     * @param {number} [config.maxSpeed=5.0] - Maximum movement speed.
     * @param {number} [config.arrivalRadius=2.0] - Arrival detection radius.
     * @returns {AgentController|null} Created agent or null if limit reached.
     */
    createPlayerAgent(bodyIndex: number, config?: {
        maxSpeed?: number;
        arrivalRadius?: number;
    }): AgentController | null;
    /**
     * Set destination for player agent, auto-creating the agent if needed.
     * This is used by body.navigation for click-to-go pathfinding.
     *
     * @param {number} bodyIndex - Body index (usually 0 for the player).
     * @param {THREE.Vector3} destination - Target world position.
     * @param {Object} [config] - Agent configuration (used if creating new agent).
     */
    setPlayerDestination(bodyIndex: number, destination: THREE.Vector3, config?: any): void;
    /**
     * Check if player agent is actively navigating.
     *
     * @param {number} bodyIndex - Body index.
     * @returns {boolean} True if navigating.
     */
    isPlayerNavigating(bodyIndex: number): boolean;
    /**
     * Check if player agent has arrived.
     *
     * @param {number} bodyIndex - Body index.
     * @returns {boolean} True if arrived.
     */
    hasPlayerArrived(bodyIndex: number): boolean;
    /**
     * Stop player agent navigation.
     *
     * @param {number} bodyIndex - Body index.
     */
    stopPlayerAgent(bodyIndex: number): void;
    /**
     * Remove pathfinding agent for a body.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} [bodyType='kinematic'] - Body type ('dynamic' or 'kinematic').
     */
    removeAgent(bodyIndex: number, bodyType?: string): void;
    /**
     * Set navigation destination for an agent.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type ('dynamic' or 'kinematic').
     * @param {THREE.Vector3} destination - Target world position.
     * @param {Function} [onArrived] - Callback when arrived.
     * @param {Function} [onPathFailed] - Callback if no path found.
     * @param {number} [version=0] - Destination version for invalidating stale paths.
     */
    setDestination(bodyIndex: number, bodyType: string, destination: THREE.Vector3, onArrived?: Function, onPathFailed?: Function, version?: number): void;
    /**
     * Stop navigation for an agent.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} [bodyType='kinematic'] - Body type ('dynamic' or 'kinematic').
     */
    stopAgent(bodyIndex: number, bodyType?: string): void;
    /**
     * Update all agents - called from physics worker each frame.
     *
     * @param {number} delta - Time delta in seconds.
     */
    update(delta: number): void;
    /**
     * Get body reference from physicsState.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type.
     * @returns {Object|null} Body object or null.
     * @private
     */
    private _getBody;
    /**
     * Get shared buffer view for body.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type.
     * @returns {Object|null} Shared buffer view or null.
     * @private
     */
    private _getSharedBuffer;
    /**
     * Queue grid generation for bounds.
     *
     * @param {THREE.Box3} bounds - Area to generate.
     * @private
     */
    private _queueGridGeneration;
    /**
     * Process grid generation queue with budget.
     *
     * @private
     */
    private _processGridQueue;
    /**
     * Get agent state for a body.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} [bodyType='kinematic'] - Body type ('dynamic' or 'kinematic').
     * @returns {number|null} Agent state or null.
     */
    getAgentState(bodyIndex: number, bodyType?: string): number | null;
    /**
     * Check if agent is navigating.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} [bodyType='kinematic'] - Body type ('dynamic' or 'kinematic').
     * @returns {boolean} True if navigating.
     */
    isNavigating(bodyIndex: number, bodyType?: string): boolean;
    /**
     * Check if agent has arrived.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} [bodyType='kinematic'] - Body type ('dynamic' or 'kinematic').
     * @returns {boolean} True if arrived.
     */
    hasArrived(bodyIndex: number, bodyType?: string): boolean;
    /**
     * Check if agent is navigating with direct position mode.
     * Used to skip dynamicPosition integration for bodies controlled by pathfinding.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} [bodyType='dynamic'] - Body type ('dynamic' or 'kinematic').
     * @returns {boolean} True if navigating with direct position updates.
     */
    isDirectPositionNavigating(bodyIndex: number, bodyType?: string): boolean;
    /**
     * Clear all agents and reset state.
     */
    clear(): void;
    /**
     * Get debug info.
     *
     * @returns {Object} Debug information.
     */
    getDebugInfo(): any;
    /**
     * Get path data for a specific agent (for debug visualization).
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} [bodyType='kinematic'] - Body type ('dynamic' or 'kinematic').
     * @returns {Object|null} Path data or null if no agent/path.
     */
    getAgentPathData(bodyIndex: number, bodyType?: string): any | null;
    /**
     * Get path data for all agents (for debug visualization).
     *
     * @returns {Object} Map of composite key (bodyType_bodyIndex) to path data.
     */
    getAllPathData(): any;
    /**
     * Pre-compute the navigation grid for a given bounds.
     * Use this to generate the full grid upfront instead of lazily.
     *
     * @param {Object} bounds - { minX, maxX, minZ, maxZ } in world units.
     */
    precomputeGrid(bounds: any): void;
    /**
     * Get navigation grid debug data.
     *
     * @returns {Object} Grid cells and info.
     */
    getNavigationGridData(): any;
}
export const physicsPathfinding: PhysicsPathfinding;
import { AgentState } from './AgentController.js';
import { PhysicsPathfindingGrid } from './PhysicsPathfindingGrid.js';
import { PathFinder } from './PathFinder.js';
import { NavMesh } from './NavMesh.js';
import { NavMeshFinder } from './NavMeshFinder.js';
import { AgentController } from './AgentController.js';
export { AgentState };
